-- gap cmp:122:13:2, written by an automated writer
test("breakit Drive.Danger: an enemy nameplate exactly at the near limit does not start a fight", function()
    local w = T.newWorld({})
    local r = T.rider(w, T.TESTCHAR, { spot = "Orgrimmar", class = "WARLOCK" })
    w:addBot("Ally Foe", { faction = "Alliance", spot = "Orgrimmar" })
    T.settle(w)
    r.api.InCombatLockdown = function() return false end
    r.api.UnitAffectingCombat = function() return false end
    r.api.UnitIsUnit = function() return false end
    local isPlayer = r.api.UnitIsPlayer
    r.api.UnitIsPlayer = function(unit)
        if unit == "target" then return false end
        return isPlayer(unit)
    end
    r.W.Drive.SetOpen(true)
    T.settle(w, 2)
    w:pvpFight(r, "Ally Foe")
    w:advance(30)
    r.api.UnitAffectingCombat = function(unit) return unit ~= "target" end
    r:fire("PLAYER_REGEN_DISABLED")
    eq((r.W.Drive.DangerLevel()), 1, "the sighting has expired and is not a fight")
    T.clean(w)
end)

-- gap cmp:171:43:2, written by an automated writer
test("breakit Drive.Danger: a fight exactly five minutes old no longer alerts the crew", function()
	local w = T.newWorld()
	local ana = T.driver(w, T.ANA)
	w:addBot("Crew Mate", { spot = "Ratchet" })
	w:group({ T.ANA, "Crew Mate" })
	T.settle(w)
	local DR = ana.W.Drive
	DR.SetOpen(true)
	local function his()
		local n = 0
		for _, e in ipairs(w.addonLog) do
			if e.prefix == "WUBERT" and e.from == T.ANA and e.text:match("^HI~") then n = n + 1 end
		end
		return n
	end
	local before = his()
	local t = 1000
	DR.danger.fightAt = t - DR.DANGER.FIGHT
	DR.danger.seenAt = nil
	DR.danger.mine = 0
	DR.danger.hiLevel = 0
	DR.danger.level = 0
	DR.DangerTick(t)
	eq(his(), before, "a fight exactly at the limit sends no early HI")
	T.clean(w)
end)

