-- gap cmp:226:23:1, written by an automated writer
test("breakit Drive.Danger: the beacon still warns of my fight when a crewmate has only seen an enemy", function()
	local w = T.newWorld()
	local d = T.driver(w, T.ANITA, { spot = "Ratchet" })
	T.settle(w)
	T.goOnline(d, { price = 5000 })
	w:advance(6)
	local DR = d.W.Drive
	DR.IsCrewKey = function(key) return key == "mate" end
	-- I fought an enemy player 200 s ago (level 2); a crewmate only saw one 5 s ago (level 1)
	DR.danger.fightAt = d.env.GetTime() - 200
	DR.DangerHeard("mate", "1:5:")
	w:advance(2)
	local all = T.msgs(w, "D", T.ANITA)
	local f = T.fields(all[#all])
	ok(f[20] and f[20]:match("^2:"), "the driver's beacon still says a hot drop: " .. tostring(f[20]))
	T.clean(w)
end)
